#define SDA_PIN 21
#define SCL_PIN 22
#define INA226_ADDRESS 0x40

// 100A / 75mV shunt
const float SHUNT_OHMS = 0.00075;

// INA226 shunt voltage resolution
const float INA226_SHUNT_LSB_V = 0.0000025;

// =====================================================
// BATTERY VOLTAGE SENSOR
// =====================================================

// Physical pin labeled D34
#define BATTERY_VOLTAGE_PIN 34

// Your measured calibration:
//
// Battery = 13.25 V
// Sensor  = 2.63 V
//
// 13.25 / 2.63 = 5.038

const float VOLTAGE_DIVIDER_RATIO = 5.038;

// Additional software calibration.
// Leave at 1.000 initially.
// We can fine-tune this against your multimeter later.

const float VOLTAGE_CALIBRATION = 1.000;

