// =====================================================
// BATTERY MONITOR STATE
// =====================================================

float batteryVoltage = 0.0;

float shuntVoltage_mV = 0.0;

float current_A = 0.0;

float filteredCurrent_A = 0.0;

float power_W = 0.0;

float peakCurrent_A = 0.0;

float sessionAh = 0.0;

// =====================================================
// TIMING
// =====================================================

const unsigned long SAMPLE_INTERVAL_MS = 100;

unsigned long lastSampleMillis = 0;

unsigned long sessionStartMillis = 0;

// =====================================================
// READ INA226 REGISTER
// =====================================================

bool readINA226Register(
  uint8_t reg,
  int16_t &value
) {

  Wire.beginTransmission(
    INA226_ADDRESS
  );

  Wire.write(reg);

  if (
    Wire.endTransmission(false) != 0
  ) {
    return false;
  }

  Wire.requestFrom(
    INA226_ADDRESS,
    (uint8_t)2
  );

  if (
    Wire.available() < 2
  ) {
    return false;
  }

  uint16_t raw =
    ((uint16_t)Wire.read() << 8)
    | Wire.read();

  value = (int16_t)raw;

  return true;
}

// =====================================================
// READ INA226 SHUNT VOLTAGE
// =====================================================

bool readShuntVoltage(
  float &millivolts
) {

  int16_t raw;

  // INA226 register 0x01
  // = shunt voltage

  if (
    !readINA226Register(
      0x01,
      raw
    )
  ) {
    return false;
  }

  float volts =
    raw *
    INA226_SHUNT_LSB_V;

  millivolts =
    volts * 1000.0;

  return true;
}

// =====================================================
// READ BATTERY VOLTAGE
// =====================================================

float readBatteryVoltage() {

  // Take multiple samples because
  // ESP32 ADC readings can be noisy.

  const int SAMPLE_COUNT = 32;

  uint32_t totalMillivolts = 0;

  for (
    int i = 0;
    i < SAMPLE_COUNT;
    i++
  ) {

    totalMillivolts +=
      analogReadMilliVolts(
        BATTERY_VOLTAGE_PIN
      );

    delayMicroseconds(200);
  }

  float sensorMillivolts =
    totalMillivolts /
    (float)SAMPLE_COUNT;

  float sensorVolts =
    sensorMillivolts /
    1000.0;

  float calculatedBatteryVoltage =
    sensorVolts *
    VOLTAGE_DIVIDER_RATIO *
    VOLTAGE_CALIBRATION;

  return calculatedBatteryVoltage;
}

// =====================================================
// UPDATE BATTERY MONITOR
// =====================================================

void updateBatteryMonitor() {

  unsigned long now =
    millis();

  if (
    now - lastSampleMillis <
    SAMPLE_INTERVAL_MS
  ) {
    return;
  }

  unsigned long elapsedMs =
    now - lastSampleMillis;

  lastSampleMillis = now;

  // ---------------------------------------------------
  // BATTERY VOLTAGE
  // ---------------------------------------------------

  batteryVoltage =
    readBatteryVoltage();

  // ---------------------------------------------------
  // CURRENT
  // ---------------------------------------------------

  float newShunt_mV;

  if (
    readShuntVoltage(
      newShunt_mV
    )
  ) {

    shuntVoltage_mV =
      newShunt_mV;

    float shuntVoltage_V =
      shuntVoltage_mV /
      1000.0;

    current_A =
      shuntVoltage_V /
      SHUNT_OHMS;

    // Ignore tiny zero-current noise

    if (
      current_A > -0.01 &&
      current_A < 0.01
    ) {

      current_A = 0.0;
    }

    // Smooth displayed current

    const float alpha = 0.25;

    filteredCurrent_A =
      (alpha * current_A) +
      ((1.0 - alpha) *
       filteredCurrent_A);

    // Peak current

    float absoluteCurrent =
      fabs(current_A);

    if (
      absoluteCurrent >
      peakCurrent_A
    ) {

      peakCurrent_A =
        absoluteCurrent;
    }

    // -------------------------------------------------
    // AMP HOURS
    // -------------------------------------------------

    float elapsedHours =
      elapsedMs /
      3600000.0;

    sessionAh +=
      current_A *
      elapsedHours;
  }

  // ---------------------------------------------------
  // POWER
  //
  // Watts = Volts x Amps
  // ---------------------------------------------------

  power_W =
    batteryVoltage *
    filteredCurrent_A;
}

// =====================================================
// RESET SESSION
// =====================================================

void resetSession() {

  peakCurrent_A = 0.0;

  sessionAh = 0.0;

  sessionStartMillis =
    millis();
}

// =====================================================
// SESSION RUNTIME
// =====================================================

String formatRuntime() {

  unsigned long seconds =
    (millis() -
     sessionStartMillis) /
    1000;

  unsigned long hours =
    seconds / 3600;

  unsigned long minutes =
    (seconds % 3600) / 60;

  seconds =
    seconds % 60;

  char buffer[20];

  snprintf(
    buffer,
    sizeof(buffer),
    "%02lu:%02lu:%02lu",
    hours,
    minutes,
    seconds
  );

  return String(buffer);
}

// =====================================================
// LIGHTING FUNCTIONS
// =====================================================

void showCurrentColor() {

  if (!lightsOn) {

    strip.clear();
    strip.show();

    return;
  }

  for (
    int i = 0;
    i < LED_COUNT;
    i++
  ) {

    strip.setPixelColor(
      i,
      strip.Color(
        currentR,
        currentG,
        currentB
      )
    );
  }

  strip.show();
}

void setColor(
  uint8_t r,
  uint8_t g,
  uint8_t b
) {

  currentR = r;
  currentG = g;
  currentB = b;

  lightsOn = true;

  showCurrentColor();
}

void returnHome() {

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303,
    "text/plain",
    ""
  );
}

